from pathlib import Path
p=Path(__file__).resolve().parents[1]/'assets';js=(p/'course-tools.js').read_text()
def page(name,title,body,script):
 (p/name).write_text('<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>body{max-width:780px;margin:auto;padding:24px;color:#26383b;background:#fafafa;font:17px/1.8 system-ui}label{display:block;margin:16px 0}input,select,button{font:inherit;padding:8px}button{margin:8px}output{display:block;white-space:pre-wrap}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccd6d8;padding:8px}.scroll{overflow-x:auto}svg{max-width:100%;height:auto}input{max-width:100%;box-sizing:border-box}</style></head><body><h1>'+title+'</h1><p>虛構教學參考成品；可作恢復點，仍需實際測試。</p>'+body+'<script>'+js+'</script><script>'+script+'</script></body></html>')
page('reference-timer.html','三分鐘計時器','<output id="clock" aria-live="off" style="font-size:3rem">03:00</output><button id="start">開始</button><button id="pause">暫停</button><button id="reset">重設</button><p id="state" role="status">已停止</p>', '''const initial=180000;let remaining=initial,deadline=null,loop=null;const display=()=>{const sec=Math.ceil(remaining/1000);document.getElementById('clock').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')};function stop(){if(deadline!==null)remaining=Math.max(0,deadline-performance.now());deadline=null;clearInterval(loop);loop=null;display()};function tick(){remaining=Math.max(0,deadline-performance.now());display();if(!remaining){stop();document.getElementById('state').textContent='時間到'}};document.getElementById('start').onclick=()=>{if(deadline!==null||!remaining)return;deadline=performance.now()+remaining;loop=setInterval(tick,100);document.getElementById('state').textContent='倒數中'};document.getElementById('pause').onclick=()=>{stop();document.getElementById('state').textContent='已暫停'};document.getElementById('reset').onclick=()=>{stop();remaining=initial;display();document.getElementById('state').textContent='已停止'};''')
page('reference-quote.html','虛構報價工具','''<form id="quote"><label>月費<select name="fee"><option value="30000">基礎30000</option><option value="60000">進階60000</option><option value="100000">客製100000</option></select></label><label>月數<select name="months"><option>3</option><option>6</option><option>12</option></select></label><label>折扣%<input name="discount" type="number" min="0" max="30" step="0.1" value="0" required></label><label>付款<select name="payment"><option value="month">月付</option><option value="quarter">季付</option><option value="year">年付</option></select></label><label><input name="tax" type="checkbox" checked>含示範稅5%</label><button>計算</button></form><output id="result" aria-live="polite"></output>''',r'''const f=document.getElementById('quote'),out=document.getElementById('result');f.addEventListener('input',()=>out.textContent='條件已變更，請重新計算');f.onsubmit=e=>{e.preventDefault();out.textContent='';try{const x=Object.fromEntries(new FormData(f));x.tax=f.elements.tax.checked;const q=Gen36.quote(x);out.textContent='稅前：'+q.net+'\n總額：'+q.total+'\n合計折扣：'+q.discountPercent+'%\n各期：'+q.installments.join('、')}catch(e){out.textContent=e.message}};''')
page('reference-chart.html','固定月營收圖表','<label>選擇CSV<input id="file" type="file" accept=".csv,text/csv"></label><output id="status" role="status">請選擇sales-24-months.csv</output><div id="chart"></div><div class="scroll"><table id="table"></table></div>', '''const status=document.getElementById('status'),table=document.getElementById('table'),chart=document.getElementById('chart');document.getElementById('file').onchange=async e=>{table.replaceChildren();chart.replaceChildren();try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('CSV過大');const lines=(await file.text()).replace(/^\\uFEFF/,'').trim().split(/\\r?\\n/);if(lines.shift()!=='month,revenue,orders')throw Error('表頭須為month,revenue,orders');const rows=lines.map(l=>{const v=l.split(',');if(v.length!==3)throw Error('每列須三欄');return{month:v[0],revenue:v[1],orders:v[2]}});const s=Gen36.stats(rows);status.textContent='月份：'+s.rows.length+'；總營收：'+s.total+'；總訂單：'+s.orders+'；客單價：'+(s.average===null?'無法計算':s.average.toFixed(2));const head=table.insertRow();['月份','營收','訂單','年增率'].forEach(t=>{const th=document.createElement('th');th.textContent=t;head.append(th)});const yoy=new Map(s.yoy.map(x=>[x.month,x.percent]));for(const r of s.rows){const tr=table.insertRow();const y=yoy.get(r.month);[r.month,r.revenue,r.orders,y===undefined||y===null?'缺前一年資料或前值為0':y.toFixed(2)+'%'].forEach(v=>tr.insertCell().textContent=v)};const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 720 220');svg.setAttribute('role','img');svg.setAttribute('aria-label','月營收，詳細數值見下方表格');const line=document.createElementNS(ns,'polyline'),max=Math.max(...s.rows.map(r=>r.revenue),1);line.setAttribute('points',s.rows.map((r,i)=>(20+i*680/Math.max(s.rows.length-1,1))+','+(200-r.revenue/max*180)).join(' '));line.setAttribute('fill','none');line.setAttribute('stroke','#446c73');line.setAttribute('stroke-width','3');svg.append(line);chart.append(svg)}catch(error){status.textContent=error.message}};''')
print('Created 3 standalone reference HTML tools')
